lines+=['',f"{comparison['improving_groups']}/4 independently prepared pairs and {comparison['improving_blocks']}/64 alternating blocks improved. Four pairs ×16 blocks ×31 calls ×2 variants produce 3,968 timed observations. Blocks within one pair are descriptive, not independent repetitions."]
adverse=s['contrary_primary_groups']
lines.append('Adverse or unchanged primary pairs: '+(', '.join(str(x['group'])+f" ({100*(x['after_over_before']-1):+.4f}%)" for x in adverse) if adverse else 'none.'))
d=s['diagnostic_cpu_elapsed'];lines+=['',f"The separate CPU-counter cohort elapsed was {d['before']['median_seconds']*1000:.6f} → {d['after']['median_seconds']*1000:.6f} ms ({d['change_percent']:+.6f}%). These 32 observations per variant are excluded from primary elapsed and retain their independent direction.",'','Other observed median increases:','','```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Binary and baseline provenance','', '| Metric | R64 baseline | R65 candidate |','|---|---:|---:|']
for key,label in [('code_bytes','Generated text bytes'),('stack_bytes','Machine entry stack bytes'),('typed_ir_version','Typed IR version'),('abi_version','ABI version')]:lines.append(f"| {label} | {s['static']['before'][key]:,} | {s['static']['after'][key]:,} |")
