for label,data in h['variants'].items():
 for f in data['functions']:lines.append(f"| {label} / `{f['needle']}` | {f['static_instruction_count']:,} | {len(f['outlined_debit_calls'])} |")
lines+=['','Raw caller/callee assembly, instruction records, TLS calls and stack adjustments are retained in `host-assembly-comparison.json` and its raw archive. Do not sum individual stack adjustments into an invented simultaneous stack depth. A later path interpretation must retain the exact branches and current TLS/account assumptions.','']
lines+=['','Object/image/metadata equality: '+str(all(s['artifact_pin_equality'].values()))+'. The unchanged generated bytes have unchanged static instruction content. Hardware retired instructions can still change because this patch changes the host checked-debit code. `binary-audit.json` records each actual image pin.', '', s['baseline_provenance']['source_note'],'',s['baseline_provenance']['binary_note'],'', 'These historical notes preserve provenance; no R64 measurement or test execution is counted as an R65 observation.','', '## Workload and correctness','', 'Input: eight bytes `abcdefgh`. Exact raw output: `[75,76,74,78,73,77,75,207,0,0]`, independently inflated. Output capacity 13 is cleared/reused. The tree has 262,144 U16 entries; the cache has 1,500,513 U32 words; depth is 300 and nice length 258. Original source allocation sites, input aliases and allocator are retained. Logical work is 60,260,219,686 and comparison work is 47,612; neither is a hardware instruction count. Successful invocations finish with zero managed bytes/nodes.','', '```json',json.dumps(s['source_pins'],indent=2),'```','', '## Qualification','',f"Status: **{s['validation']['status']}**. Counts below are actual executed receipts; inventory-only rows are omitted from this view and remain in `validation.json`. Batches overlap.",'', '| Receipt | Expected tests | Observed | Exit / expected | Passed |','|---|---:|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
 lines.append(f"| `{row['receipt']}` | {row.get('expected_tests','—')} | {row.get('observed_tests',row.get('cases','—'))} | {row.get('exit','—')} / {row.get('expected_exit',0)} | {row['passed']} |")
lines+=['',s['validation']['parent_candidate_scope'],'',s['validation']['runtime_coverage']['scope'],'','Parent Engine qualification freshly executes the pinned unchanged R64 test binary; candidate Engine tests are newly compiled against the candidate graph. The local `ci.py` Engine batches execute all 12 projection-meter tests and all six inherited frame-shape tests using the retained broader Engine test feature configuration. Core also executes its two existing first-violation equivalence/order tests afresh using the pinned unchanged R64 Core test binary. Both variants freshly execute the 12 GPU work tests and the exact ceiling/foreign-scope-order case. The complete commands are archived; this is not a claim that the local Engine build used exactly a minimal CI feature set or that remote CI completed.','', 'Earlier failed attempts and dispositions:']
for row in s['validation']['prior_failures']:lines.append('- `'+row['receipt']+'` — '+row.get('classification','unclassified')+': '+row['disposition'])
if not s['validation']['prior_failures']:lines.append('None recorded.')
lines+=['','Skipped coverage:']
for row in s['validation']['skipped_coverage']:lines.append('- '+row.get('test',row.get('coverage'))+': '+row['disposition'])
lines+=['','Decision: **'+s['decision']['status']+'**. '+s['decision']['reason'],'','## Replay','','Run `python3 reconstruct.py /new/empty/output/path` from the published packet. Replay verifies every archived file version and reproduces scorecard JSON/CSV, allocation-comparison JSON, profile JSON, validation JSON and host-assembly-comparison JSON without compilation, compressor execution or external scratch inputs.','', 'This complete small-input result does not establish larger-input throughput or a standalone minimum-memory footprint. Each reported direction and decision comes from R65 receipts; no earlier-round gains are multiplied into this result.','']
